import { index, integer, sqliteTable, text, uniqueIndex } from 'drizzle-orm/sqlite-core'

// better-auth tables, generated by `pnpm auth:schema`
export * from './auth-schema'

/** Key/value settings: mcp_path_secret, base_url, allow_dcr, allowed_cidrs, ... */
export const setting = sqliteTable('setting', {
  key: text('key').primaryKey(),
  value: text('value').notNull(),
})

/** One row per configured connector (id = connector type for now). */
export const connector = sqliteTable('connector', {
  id: text('id').primaryKey(),
  type: text('type').notNull(),
  name: text('name').notNull(),
  baseUrl: text('base_url'),
  /** JSON of the config; fields marked secret() are encrypted individually (lib/crypto.ts) */
  configEnc: text('config_enc').notNull(),
  enabled: integer('enabled', { mode: 'boolean' }).notNull().default(true),
  /** JSON array of tool names switched off in the admin panel */
  disabledTools: text('disabled_tools', { mode: 'json' }).$type<string[]>().notNull().default([]),
  lastCheckAt: integer('last_check_at', { mode: 'timestamp_ms' }),
  lastCheckOk: integer('last_check_ok', { mode: 'boolean' }),
  lastCheckNote: text('last_check_note'),
  updatedAt: integer('updated_at', { mode: 'timestamp_ms' }).notNull(),
})

/** result_id cache for search results: the hub keeps links, Claude only sees the id. */
export const searchResult = sqliteTable('search_result', {
  id: text('id').primaryKey(),
  connectorId: text('connector_id').notNull(),
  payloadJson: text('payload_json').notNull(),
  expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
})

/** HTML prototypes; files live in /data/prototypes/{id}/v{version}.html */
export const prototype = sqliteTable('prototype', {
  id: text('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  title: text('title').notNull(),
  pinHash: text('pin_hash'),
  /** Bumped on every pin change: invalidates access cookies */
  pinVersion: integer('pin_version').notNull().default(0),
  /** Digits in the pin, so the pin page shows exactly that many cells; null for pins set before it was stored */
  pinLength: integer('pin_length'),
  expiresAt: integer('expires_at', { mode: 'timestamp_ms' }),
  sizeBytes: integer('size_bytes').notNull(),
  version: integer('version').notNull().default(1),
  views: integer('views').notNull().default(0),
  lastViewedAt: integer('last_viewed_at', { mode: 'timestamp_ms' }),
  createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp_ms' }).notNull(),
})

/** Journal: every tool call and admin sign-in. Arguments are redacted and cut to 500 chars. */
export const toolCall = sqliteTable('tool_call', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  /** Tool name, or auth.* for sign-in events */
  tool: text('tool').notNull(),
  /** Connector id, 'hub' for hub_status, 'auth' for sign-ins */
  connectorId: text('connector_id').notNull(),
  argsRedacted: text('args_redacted').notNull(),
  ok: integer('ok', { mode: 'boolean' }).notNull(),
  /** First line of the result, for the journal */
  resultSummary: text('result_summary'),
  error: text('error'),
  durationMs: integer('duration_ms'),
  clientId: text('client_id'),
  ip: text('ip'),
  createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
}, (t) => [index('tool_call_created_at_idx').on(t.createdAt), index('tool_call_client_idx').on(t.clientId)])

/** Paperless metadata edits made through the hub: before/after for undo, grouped by batch. */
export const paperlessChange = sqliteTable('paperless_change', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  batchId: text('batch_id').notNull(),
  documentId: integer('document_id').notNull(),
  beforeJson: text('before_json').notNull(),
  afterJson: text('after_json').notNull(),
  undoneAt: integer('undone_at', { mode: 'timestamp_ms' }),
  createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
}, (t) => [index('paperless_change_batch_idx').on(t.batchId)])

/** Download links for documents: personal (admin session required) or shareable (one-time, short). */
export const downloadLink = sqliteTable('download_link', {
  token: text('token').primaryKey(),
  connectorId: text('connector_id').notNull(),
  documentId: integer('document_id').notNull(),
  original: integer('original', { mode: 'boolean' }).notNull().default(false),
  shareable: integer('shareable', { mode: 'boolean' }).notNull().default(false),
  expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
  usedAt: integer('used_at', { mode: 'timestamp_ms' }),
  createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
})

/** Cron scripts written by the assistant; run only while the approved code hash matches. */
export const script = sqliteTable('script', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  description: text('description').notNull().default(''),
  schedule: text('schedule').notNull(),
  code: text('code').notNull(),
  codeHash: text('code_hash').notNull(),
  approvedHash: text('approved_hash'),
  approvedCode: text('approved_code'),
  approvedAt: integer('approved_at', { mode: 'timestamp_ms' }),
  rejectedHash: text('rejected_hash'),
  rejectReason: text('reject_reason'),
  enabled: integer('enabled', { mode: 'boolean' }).notNull().default(false),
  lastRunAt: integer('last_run_at', { mode: 'timestamp_ms' }),
  lastRunOk: integer('last_run_ok', { mode: 'boolean' }),
  createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp_ms' }).notNull(),
})

export const scriptRun = sqliteTable('script_run', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  scriptId: text('script_id').notNull().references(() => script.id, { onDelete: 'cascade' }),
  trigger: text('trigger').notNull(),
  ok: integer('ok', { mode: 'boolean' }).notNull(),
  output: text('output'),
  logs: text('logs'),
  error: text('error'),
  durationMs: integer('duration_ms').notNull(),
  startedAt: integer('started_at', { mode: 'timestamp_ms' }).notNull(),
}, (t) => [index('script_run_script_idx').on(t.scriptId, t.startedAt)])

/** Secrets for scripts: encrypted, substituted into requests only for their allowed hosts. */
export const scriptSecret = sqliteTable('script_secret', {
  name: text('name').primaryKey(),
  valueEnc: text('value_enc').notNull(),
  hosts: text('hosts', { mode: 'json' }).$type<string[]>().notNull(),
  description: text('description').notNull().default(''),
  updatedAt: integer('updated_at', { mode: 'timestamp_ms' }).notNull(),
})

/** Small key/value memory per script between runs. */
export const scriptState = sqliteTable('script_state', {
  scriptId: text('script_id').notNull().references(() => script.id, { onDelete: 'cascade' }),
  key: text('key').notNull(),
  valueJson: text('value_json').notNull(),
}, (t) => [uniqueIndex('script_state_pk').on(t.scriptId, t.key)])
